import sys, json
def make_sim(table):
    maxlen = max(len(k) for k in table)
    def sim(s):
        out=[]; i=0
        while i < len(s):
            for L in range(min(maxlen, len(s)-i), 0, -1):
                sub = s[i:i+L]
                if sub in table:
                    out.append(table[sub]); i+=L; break
            else:
                out.append(s[i]); i+=1
        return ''.join(out)
    return sim
EOF
